  au.id, au.id,
  pd.first_name, pd.last_name, pd.phone, pd.real_email,
  pd.gender::gender_type,
  pd.dob::date,
  pd.address,
  pd.medical_history, pd.dental_history,
  pd.legacy_code, pd.username,
  pd.reg_date::timestamptz, now()
