  ON au.email = pd.auth_email
ON CONFLICT (id) DO NOTHING;

-- ─────────────────────────────────────────────────────────────
-- 3C. Create auth.identities (required for email/password login)
-- ─────────────────────────────────────────────────────────────
INSERT INTO auth.identities (
  provider_id, user_id, identity_data, provider,
  last_sign_in_at, created_at, updated_at
)
SELECT
  au.email,
  au.id,
  jsonb_build_object('sub', au.id::text, 'email', au.email),
  'email',
  now(), au.created_at, now()
FROM public.patients p
JOIN auth.users au ON au.id = p.auth_user_id
WHERE p.legacy_patient_code IS NOT NULL
ON CONFLICT (provider_id, provider) DO NOTHING;

-- ─────────────────────────────────────────────────────────────
-- Verification
-- ─────────────────────────────────────────────────────────────
SELECT
  COUNT(*)                           AS total_patients,
  COUNT(auth_user_id)                AS with_auth_account,
  COUNT(legacy_patient_code)         AS with_legacy_code,
  COUNT(CASE WHEN username IS NOT NULL THEN 1 END) AS with_username,
  COUNT(CASE WHEN date_of_birth IS NOT NULL THEN 1 END) AS with_dob,
  COUNT(CASE WHEN email IS NOT NULL THEN 1 END) AS with_real_email
FROM public.patients;

